INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440009353102015, ARRAY['"A user enters example.com and receives the matching IP address before connecting to the site. Which service most directly performs this name resolution?"'::jsonb, '"A page loads HTML successfully, but a separately linked style file cannot be fetched. Which request/result is most relevant to investigate?"'::jsonb, '"A form submits login details over an unencrypted HTTP connection. What is the primary risk?"'::jsonb, '"A browser sends web requests, but the app needs reliable, ordered delivery for the data. Which transport is typically appropriate?"'::jsonb, '"A real-time service prefers low overhead and can tolerate some packet loss without waiting for retransmission. Which transport may fit?"'::jsonb, '"A user needs to transfer a file to a server using the protocol named in the syllabus. Which choice fits?"'::jsonb, '"A developer serves the same HTML document over HTTP and HTTPS. What does the HTTPS version add when configured correctly?"'::jsonb, '"A site owner changes a domain''s DNS record but some users still reach the old server temporarily. Which explanation is plausible?"'::jsonb, '"A site is accessible from a network but not by entering its domain, while a known IP address works. Which issue is worth checking first?"'::jsonb, '"A website uses a numeric IPv4 address and a newer 128-bit IPv6 address. Which statement is correct?"'::jsonb]::jsonb[], ARRAY['"CSS"'::jsonb, '"HTML"'::jsonb, '"DNS"'::jsonb, '"FTP"'::jsonb, '"The table''s colspan"'::jsonb, '"The user''s keyboard layout"'::jsonb, '"The image''s alt text alone"'::jsonb, '"The stylesheet URL and server response for the CSS resource"'::jsonb, '"Credentials may be exposed in transit"'::jsonb, '"HTML elements stop being parsed"'::jsonb, '"DNS converts the password into a domain"'::jsonb, '"The CSS box model stops working"'::jsonb, '"CSS"'::jsonb, '"TCP"'::jsonb, '"FTP only"'::jsonb, '"UDP"'::jsonb, '"HTTPS"'::jsonb, '"TCP"'::jsonb, '"HTML"'::jsonb, '"UDP"'::jsonb, '"HTTP heading"'::jsonb, '"FTP"'::jsonb, '"CSS selector"'::jsonb, '"JPEG"'::jsonb, '"Guaranteed correctness of every page statement"'::jsonb, '"A mandatory CSS grid layout"'::jsonb, '"TLS protection for data exchanged between client and server"'::jsonb, '"Automatic correction of invalid HTML"'::jsonb, '"Cached DNS data may persist until its TTL or cache expires"'::jsonb, '"HTTPS disables IP addressing"'::jsonb, '"CSS specificity always overrides DNS"'::jsonb, '"HTML lists are controlling routing"'::jsonb, '"Table row span"'::jsonb, '"DNS/name resolution"'::jsonb, '"Font weight"'::jsonb, '"Image width"'::jsonb, '"Both versions are HTML tags"'::jsonb, '"IPv6 is a CSS stylesheet type"'::jsonb, '"IPv4 uses 128 bits and IPv6 uses 32"'::jsonb, '"IPv4 uses 32-bit addresses; IPv6 uses 128-bit addresses"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440009353102016, ARRAY['"A registration form needs a name field, an email field and a submit control. Which HTML approach fits best?"'::jsonb, '"A survey allows a user to select several interests independently. Which control is usually appropriate?"'::jsonb, '"A form asks users to select exactly one department from four options. Which is the better choice?"'::jsonb, '"A web form needs a dropdown of department names and a default prompt that is not a valid department. What should the developer do?"'::jsonb, '"A data table has a header cell that labels three adjacent columns. Which attribute can help achieve this structure?"'::jsonb, '"A table has one category label that should cover two rows. Which attribute fits?"'::jsonb, '"A hyperlink to syllabus.html works on one page but fails from a page in a subfolder. What should be checked first?"'::jsonb, '"A page must link to a full external website. Which href is generally unambiguous?"'::jsonb, '"A form''s reset control should restore controls to their initial values rather than send the form. Which input type is designed for this?"'::jsonb, '"Which hidden form field behavior should a developer remember?"'::jsonb]::jsonb[], ARRAY['"Create each field as an image"'::jsonb, '"Use only heading elements"'::jsonb, '"Use a definition list instead of controls"'::jsonb, '"Use suitable input types inside a form with a submit button"'::jsonb, '"Checkboxes"'::jsonb, '"Radio buttons in one named group"'::jsonb, '"A single text heading"'::jsonb, '"A submit button only"'::jsonb, '"A hidden input only"'::jsonb, '"Radio buttons sharing the same name"'::jsonb, '"A paragraph element"'::jsonb, '"Four independent checkboxes"'::jsonb, '"Place the list inside a CSS comment"'::jsonb, '"Make the options separate h1 elements"'::jsonb, '"Create a select element with option elements, including a clearly marked prompt option"'::jsonb, '"Use colspan on the submit button"'::jsonb, '"colspan=\"3\""'::jsonb, '"rowspan=\"3\""'::jsonb, '"href=\"3\""'::jsonb, '"alt=\"3\""'::jsonb, '"src=\"2\""'::jsonb, '"action=\"2\""'::jsonb, '"rowspan=\"2\""'::jsonb, '"colspan=\"2\""'::jsonb, '"The table header colour"'::jsonb, '"The CSS font-weight"'::jsonb, '"The form''s radio group"'::jsonb, '"The relative path from the current page"'::jsonb, '"style.css"'::jsonb, '"https://example.com/"'::jsonb, '"#heading"'::jsonb, '"submit"'::jsonb, '"hidden"'::jsonb, '"image only"'::jsonb, '"reset"'::jsonb, '"submit"'::jsonb, '"Its value is still submitted and must not be treated as secret merely because it is hidden"'::jsonb, '"It replaces HTTPS"'::jsonb, '"It automatically encrypts all form data"'::jsonb, '"It is invisible to the server"'::jsonb]::jsonb[], ARRAY['3'::jsonb, '0'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440009353102017, ARRAY['"A CSS rule `.notice { color: red; }` is applied to `<p class=\"notice\">`. What does the selector target?"'::jsonb, '"A CSS rule `#menu { background: black; }` should apply to the navigation container. Which HTML attribute is needed?"'::jsonb, '"The content box is 200 px wide with 10 px padding on each side and 2 px borders on each side. Under the default content-box model, what is the rendered border-box width, excluding margins?"'::jsonb, '"A developer wants a 300 px declared width to include padding and border. Which CSS setting helps?"'::jsonb, '"Which distinction between margin and padding is correct?"'::jsonb, '"An external stylesheet is linked but its rules do not appear. Which source-level check is most direct?"'::jsonb, '"A developer places a style block in the document head. Which stylesheet type is this?"'::jsonb, '"A developer applies `color: blue` in an element''s style attribute. Which category is this?"'::jsonb, '"Which selector matches every paragraph inside a section, including deeper nested paragraphs?"'::jsonb, '"Which selector matches only paragraph elements that are direct children of a section?"'::jsonb]::jsonb[], ARRAY['"That paragraph because it has class notice"'::jsonb, '"All paragraphs only if they lack classes"'::jsonb, '"Only the element with id notice"'::jsonb, '"Every link in the page"'::jsonb, '"href=\"menu\""'::jsonb, '"id=\"menu\""'::jsonb, '"name=\".menu\""'::jsonb, '"class=\"#menu\""'::jsonb, '"244 px"'::jsonb, '"200 px"'::jsonb, '"224 px"'::jsonb, '"220 px"'::jsonb, '"box-sizing: content-only"'::jsonb, '"display: hidden"'::jsonb, '"position: font"'::jsonb, '"box-sizing: border-box"'::jsonb, '"Both are always drawn as visible borders"'::jsonb, '"Margin is outside the border; padding is between content and border"'::jsonb, '"Padding is outside the element; margin is inside content"'::jsonb, '"Margin is the text colour; padding is the font"'::jsonb, '"Change an image''s alt text"'::jsonb, '"Change the document''s title only"'::jsonb, '"Add more table rows"'::jsonb, '"Verify the href path and that the CSS file is successfully served"'::jsonb, '"Embedded/internal CSS"'::jsonb, '"Inline CSS"'::jsonb, '"External CSS only"'::jsonb, '"Browser-only user style"'::jsonb, '"Internal CSS"'::jsonb, '"Server-side CSS"'::jsonb, '"Inline CSS"'::jsonb, '"External CSS"'::jsonb, '".p"'::jsonb, '"section > p only"'::jsonb, '"#section"'::jsonb, '"section p"'::jsonb, '"section p"'::jsonb, '"section > p"'::jsonb, '"p section"'::jsonb, '".section-p"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440009353102018, ARRAY['"A card needs a soft shadow, rounded corners and a subtle background gradient. Which combination directly supports those effects?"'::jsonb, '"A tooltip should appear when a user hovers over an element. Which CSS concept can support this behavior?"'::jsonb, '"An icon should rotate without changing its place in normal document flow. Which CSS feature is designed for that visual effect?"'::jsonb, '"A small animation should progress through defined stages over time. Which CSS feature is appropriate?"'::jsonb, '"A navigation menu should remain positioned relative to its normal place, with a small offset. Which positioning mode best fits?"'::jsonb, '"A floating help control should stay at the same viewport location as the page scrolls. Which positioning mode fits?"'::jsonb, '"A badge should be positioned relative to a card whose position is set to relative. Which mode is commonly used for the badge?"'::jsonb, '"A developer uses one linked CSS file for ten HTML pages. What is the main maintenance benefit?"'::jsonb, '"A title is styled by `h1 { color: black; }` and `.hero { color: teal; }`, and the title has class hero. Assuming equal origin and no !important, which colour applies?"'::jsonb, '"A webpage should animate an element while respecting a design that avoids sudden motion for users who request reduced motion. Which approach is best?"'::jsonb]::jsonb[], ARRAY['"TCP, UDP and DNS"'::jsonb, '"box-shadow, border-radius and background-image: linear-gradient(...)"'::jsonb, '"thead, tbody and tfoot"'::jsonb, '"rowspan, href and alt"'::jsonb, '"A table''s colspan attribute"'::jsonb, '"A DNS A record only"'::jsonb, '"A :hover selector with a styled tooltip element"'::jsonb, '"The HTML doctype"'::jsonb, '"margin: rotate(...)"'::jsonb, '"font-family: rotate(...)"'::jsonb, '"href: rotate(...)"'::jsonb, '"transform: rotate(...)"'::jsonb, '"@keyframes with animation properties"'::jsonb, '"The FTP protocol"'::jsonb, '"HTML alt text"'::jsonb, '"The table tfoot element"'::jsonb, '"static only"'::jsonb, '"fixed"'::jsonb, '"relative"'::jsonb, '"absolute with no positioned ancestor always"'::jsonb, '"fixed"'::jsonb, '"static"'::jsonb, '"relative only"'::jsonb, '"table-row"'::jsonb, '"inline-only"'::jsonb, '"absolute"'::jsonb, '"inherit text"'::jsonb, '"static"'::jsonb, '"The browser stops caching resources"'::jsonb, '"Every page automatically gets a unique domain"'::jsonb, '"HTML validation is no longer needed"'::jsonb, '"A single stylesheet can update shared presentation across all pages"'::jsonb, '"teal because a class selector is more specific than a type selector"'::jsonb, '"black because type selectors always win"'::jsonb, '"Both colours are blended"'::jsonb, '"Neither rule can match an h1"'::jsonb, '"Replace animation with repeated blinking text"'::jsonb, '"Ignore the user preference"'::jsonb, '"Use a reduced-motion media query to reduce/disable nonessential animation"'::jsonb, '"Increase animation speed for everyone"'::jsonb]::jsonb[], ARRAY['1'::jsonb, '2'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440009353102019, ARRAY['"A browser can resolve a domain to an IP address, but the server returns an HTTP 404 for `/courses/sem1.html`. What is the most targeted interpretation?"'::jsonb, '"A site opens on HTTPS, but browser requests for images still use HTTP. What is the main issue to address?"'::jsonb, '"A client uploads files reliably but slowly because the transfer must recover lost data and preserve order. Which protocol comparison is accurate?"'::jsonb, '"A website is moved from one IP address to another. The domain still resolves to the old address for some users. Which pair of actions is most relevant?"'::jsonb, '"A developer makes a login page with HTTPS, but the server stores passwords as plain text. Which statement is correct?"'::jsonb, '"A developer must choose between TCP and UDP for a file upload requiring complete, ordered data. Which choice best fits and why?"'::jsonb, '"A site uses an IP address in a link instead of a domain. Which maintenance disadvantage is most plausible?"'::jsonb, '"An HTML page loads but the external CSS file returns 403 Forbidden. What should be checked before rewriting every selector?"'::jsonb, '"A domain resolves correctly and the web server responds, but HTTPS warns that the certificate is for a different hostname. What should be investigated?"'::jsonb, '"A page needs a live feed where occasional dropped packets are acceptable and low latency matters more than guaranteed transport delivery. Which transport is a plausible choice?"'::jsonb]::jsonb[], ARRAY['"The network has no IP connectivity"'::jsonb, '"DNS is definitely broken"'::jsonb, '"Name resolution and server contact worked; the requested resource path was not found"'::jsonb, '"The browser cannot parse CSS"'::jsonb, '"Change all img tags to table tags"'::jsonb, '"Replace IPv6 with an HTML selector"'::jsonb, '"Use UDP to style the image"'::jsonb, '"Mixed content: serve the image resources securely too"'::jsonb, '"TCP provides reliable ordered transport; UDP does not guarantee delivery/order"'::jsonb, '"HTTP is a CSS style type"'::jsonb, '"FTP is the IP address version"'::jsonb, '"UDP guarantees every packet is delivered in order"'::jsonb, '"Replace hyperlinks with radio buttons"'::jsonb, '"Update the appropriate DNS record and account for caching/TTL propagation"'::jsonb, '"Change the CSS ID selector and refresh font-weight"'::jsonb, '"Rename the homepage from h1 to h2"'::jsonb, '"HTTPS automatically encrypts the database at rest"'::jsonb, '"Plain-text storage is safe because the form is hidden"'::jsonb, '"CSS can replace password storage controls"'::jsonb, '"HTTPS protects data in transit; it does not by itself secure how the server stores passwords"'::jsonb, '"CSS, because it handles file transfer"'::jsonb, '"TCP, because it supplies reliability and ordered delivery"'::jsonb, '"DNS, because it sorts packets"'::jsonb, '"UDP, because it guarantees retransmission by default"'::jsonb, '"HTTPS no longer works with domains"'::jsonb, '"An IP address is always encrypted"'::jsonb, '"The link must change if the service''s address changes, while a stable domain can be repointed via DNS"'::jsonb, '"A domain name cannot resolve to an IP"'::jsonb, '"The stylesheet resource''s permissions/access rules and requested path"'::jsonb, '"The HTML5 doctype only"'::jsonb, '"Whether the page has a radio button"'::jsonb, '"Whether the site uses IPv6"'::jsonb, '"CSS margin collapse"'::jsonb, '"Certificate hostname and TLS/server configuration"'::jsonb, '"Table rowspan"'::jsonb, '"The HTML paragraph tag"'::jsonb, '"CSS"'::jsonb, '"TCP only"'::jsonb, '"FTP"'::jsonb, '"UDP"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (4400093531020110, ARRAY['"A card has width: 240px, padding: 12px on both sides and border: 3px on both sides under content-box sizing. Without margins, what is its outer width?"'::jsonb, '"An element has `position: absolute; right: 0; bottom: 0;`. Which ancestor most directly determines its positioning reference when that ancestor is positioned?"'::jsonb, '"A class selector and an ID selector both set the same property on an element, with equal origin and no !important. Which usually wins?"'::jsonb, '"A layout must remain in the normal document flow and shift 8 px down from where it would normally appear. Which setting most directly fits?"'::jsonb, '"A developer sets an image width and height to fixed dimensions but aspect ratio becomes distorted. What is a sensible correction?"'::jsonb, '"A CSS background gradient is visible, but text contrast is poor on part of the card. What is the best fix?"'::jsonb, '"A tooltip is clipped inside a container that has overflow hidden. What should be inspected?"'::jsonb, '"A site requires animations to run only when reduced motion is not requested. Which CSS organization best meets that constraint?"'::jsonb, '"External CSS is linked correctly, but inline style sets a different color on one element. Which explanation commonly applies?"'::jsonb, '"An absolutely positioned menu overlays a button and intercepts its clicks. Which CSS concept may help control which item appears above the other?"'::jsonb]::jsonb[], ARRAY['"240 px"'::jsonb, '"264 px"'::jsonb, '"300 px"'::jsonb, '"270 px"'::jsonb, '"The nearest positioned ancestor"'::jsonb, '"The nearest paragraph regardless of positioning"'::jsonb, '"The DNS resolver"'::jsonb, '"Always the HTML title"'::jsonb, '"Neither because they conflict"'::jsonb, '"The ID selector due to higher specificity"'::jsonb, '"The class selector always"'::jsonb, '"The later HTML tag name regardless of CSS order"'::jsonb, '"position: fixed; top: 8px"'::jsonb, '"position: absolute; top: 8px with no containing block"'::jsonb, '"position: relative; top: 8px"'::jsonb, '"display: none"'::jsonb, '"Set one dimension and preserve the intrinsic aspect ratio, or use an appropriate object-fit behavior"'::jsonb, '"Add a colspan attribute to the image"'::jsonb, '"Switch HTTP to FTP"'::jsonb, '"Use font-weight to restore the image shape"'::jsonb, '"Set the HTML title to the same colour"'::jsonb, '"Increase the animation duration only"'::jsonb, '"Adjust the gradient/overlay or text colour to maintain readable contrast across the background"'::jsonb, '"Replace the background with a hyperlink"'::jsonb, '"The site''s DNS record"'::jsonb, '"The HTML doctype only"'::jsonb, '"The table''s tfoot"'::jsonb, '"The containing element''s overflow/positioning and the tooltip''s placement in the layout"'::jsonb, '"Use an HTML meta tag to force motion"'::jsonb, '"Define the animation as default and disable/reduce it under prefers-reduced-motion: reduce"'::jsonb, '"Use DNS caching to control animation"'::jsonb, '"Set every animation to infinite blink"'::jsonb, '"The element becomes an HTML comment"'::jsonb, '"External CSS always beats inline styles"'::jsonb, '"The inline style generally has higher priority than a normal author stylesheet rule for the same property"'::jsonb, '"The browser blends the two colours"'::jsonb, '"z-index on appropriately positioned elements"'::jsonb, '"font-family"'::jsonb, '"colspan"'::jsonb, '"DNS TTL"'::jsonb]::jsonb[], ARRAY['3'::jsonb, '0'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb]::jsonb[]);

INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
